insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es) values ('e58ca12f-7cf1-5ddd-b8a1-0b65935a9706', '223a252c-124e-55c4-ae8c-bfe6b9f7d7e7', 0, 'reading', 'Course overview', 'Resumen del curso', '## About this course
